-- 063_products_inventory_seed.sql

CREATE TABLE IF NOT EXISTS products (
  id integer PRIMARY KEY,
  item_category text NULL,
  item_quantity integer NULL DEFAULT 1,
  item_name text NULL,
  item_make text NULL,
  item_model text NULL,
  item_size text NULL,
  item_viscosity text NULL,
  item_type text NULL,
  item_brand text NULL,
  item_description text NULL,
  item_qr_code text NULL,
  vendor_id integer NULL,
  po_id integer NULL,
  location integer NULL,
  status text NULL DEFAULT 'Available',
  issue_date timestamp NULL,
  warranty_date timestamp NULL,
  supplier_date timestamp NULL,
  line_item_id integer NULL,
  cost integer NULL,
  chsc integer NULL,
  cn_image text NULL,
  deleted boolean NULL,
  date_created timestamptz NULL DEFAULT now()
);

ON CONFLICT (id) DO NOTHING;
